def ic(nom: str, cls: str = "") -> str:
    """SVG de l'icône `nom` (vide si inconnue)."""
    if nom not in ICONES:
        return ""
    return (f'<svg class="s360-ic {cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" '
            f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONES[nom]}</svg>')
